{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Tolfenamic acid, a close anthranilic acid analogue bearing a carboxylic acid, secondary arylamine, and chloro substituent, has an absolute oral bioavailability of 63.2% in healthy volunteers, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Telmisartan, a zwitterionic carboxylic acid-containing drug with challenging physicochemical properties, achieves 57.4% absolute oral bioavailability in humans, showing that acidic/polar molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Encorafenib, which contains a sulfonamide and polar heteroaromatic groups, has an oral bioavailability of at least 86%, demonstrating that sulfonamide-containing polar structures are compatible with high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Rigosertib, a carboxylic acid-containing polar molecule with a secondary amine and sulfone, has 35% absolute oral bioavailability in the fasting state, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib in the fed state shows 13.9% absolute bioavailability, providing a low-F data point, but this is food/formulation-dependent and outweighed by multiple high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is furosemide, a known loop diuretic with clinically established absolute oral bioavailability around 50% (range roughly 40–60%), well above the 20% threshold. Although the physicochemical prior predicts low permeability, multiple high-transfer experimental analogues—especially anthranilic acid derivatives (tolfenamic acid), zwitterionic carboxylic acids (telmisartan), and sulfonamide-containing drugs (encorafenib)—show absolute F values of 35–95%. The only sub-20% data point (fed rigosertib) is food-dependent and outweighed. Therefore predict high.",
  "evidence_gaps": [
    "No direct furosemide record is present in the supplied evidence set.",
    "Food effects and formulation variability for the query are not directly captured.",
    "Permeability and transporter-mediated absorption of the query were not experimentally measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

